import System.IO (isEOF)

loop :: IO ()
loop = do
  done <- isEOF
  if done
    then return ()
    else do
      [a, b] <- map read . words <$> getLine :: IO [Int]
      print (a + b)
      loop

main :: IO ()
main = loop

